import React, { useEffect, useState } from "react";
import { Box, Badge, Stack, Avatar, Typography, IconButton, Button, } from "@mui/material";
import { styled, useTheme } from "@mui/material/styles";
import { Chat, FingerprintSimple, X } from "phosphor-react";
import StyledBadge from "./StyledBadge";
import webSocketService from "../webSocketService";

const StyledChatBox = styled(Box)(({ theme }) => ({
  "&:hover": {
    cursor: "pointer",
  },
}));

const UserElement = ({ requestSent, requestReceived, user }) => {
  const theme = useTheme();

  const name = `${user.firstName} ${user.lastName}`;
  const user_id = window.localStorage.getItem("user_id");
  const [sent, setSent] = useState(requestSent);
  const [received, setReceived] = useState(requestReceived);

  useEffect(() => {
    setSent(requestSent);
    setReceived(requestReceived);
  }, [requestSent, requestReceived])


  return (
    <StyledChatBox
      sx={{
        borderRadius: 2,
        backgroundColor: theme.palette.mode === "light" ? "#fff" : theme.palette.background.paper,
        boxShadow: "0 0 10px rgba(0, 0, 0, 0.1)",
        cursor: 'pointer',
        transition: "0.1s ease-in-out", // Smooth transition effect
        '&:hover': {
          backgroundColor: theme.palette.action.hover, // Change background color on hover
          transform: 'scale(1.05);',
        },
      }}
      p={2}
    >
      <Stack
        direction="row"
        alignItems={"center"}
        justifyContent="space-between"
      >
        <Stack direction="row" alignItems={"center"} spacing={2}>
          {" "}
          {user.status === "ONLINE" ? (
            <StyledBadge
              overlap="circular"
              anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
              variant="dot"
            >
              <Avatar alt={name} src={user.avatar} />
            </StyledBadge>
          ) : (
            <Avatar alt={name} src={user.avatar} />
          )}
          <Stack spacing={0.3}>
            <Typography variant="subtitle2">{name}</Typography>
          </Stack>
        </Stack>
        <Stack direction={"row"} spacing={2} alignItems={"center"}>
          {(() => {
            if (!sent && !received) {
              return <Button variant="contained"
                onClick={() => {
                  webSocketService.sendMessage("/app/send_friend_request", JSON.stringify({ from: user_id, to: user.id }));
                  setSent(!sent);
                }}
              >
                {"Send Request"}
              </Button>
            } else if (sent) {
              return <Button variant="text"
                sx={{
                  transition: "0.1s ease-in-out",
                  '&:hover': {
                    backgroundColor: theme.palette.primary.main, // Change background color on hover
                    color: theme.palette.text.primary,
                  },
                }}
                onClick={() => {
                  webSocketService.sendMessage("/app/cancel_friend_request", JSON.stringify({ from: user_id, to: user.id }));
                  setSent(!sent);
                }}
              >
                {"Cancel Request"}
              </Button>
            } else if (requestReceived) {
              return (
                <>
                  <Button
                    onClick={() => {
                      webSocketService.sendMessage("/app/accept_request", JSON.stringify({ sender_id: user.id, recipient_id: user_id }));
                    }}
                  >
                    Accept
                  </Button>
                  <IconButton
                    onClick={() => {
                      webSocketService.sendMessage("/app/cancel_friend_request", JSON.stringify({ from: user.id, to: user_id }));
                    }}
                  >
                    <X />
                  </IconButton>
                </>
              )
            }
          })()}
        </Stack>
      </Stack>
    </StyledChatBox>
  );
};

