// FriendElement

const FriendElement = ({ avatar, firstName, lastName, status, id, handleClose }) => {
  const theme = useTheme();

  const name = `${firstName} ${lastName}`;
  const user_id = window.localStorage.getItem("user_id");

  const [showUndo, setShowUndo] = useState(false);   // Controls undo button visibility
  const [timer, setTimer] = useState(10);            // Countdown timer value
  const [timeoutId, setTimeoutId] = useState(null);  // Stores timeout id
  const [removed, setRemoved] = useState(false);

  // Function to send WebSocket request
  const sendRemoveFriendRequest = () => {
    webSocketService.sendMessage("/app/remove_friend", JSON.stringify({ to: id, from: user_id }));
    setRemoved(true);
  };

  // Function to handle X button click
  const handleRemoveClick = () => {
    setShowUndo(true); // Show the undo button
    setTimer(10);      // Start with 10 seconds

    const id = setTimeout(() => {
      sendRemoveFriendRequest();
      setShowUndo(false);
    }, 10000);

    setTimeoutId(id);
  };

  // Function to handle Undo click
  const handleUndoClick = () => {
    clearTimeout(timeoutId);
    setShowUndo(false);
  };

  // Effect to handle the countdown timer
  useEffect(() => {
    if (showUndo && timer > 0) {
      const intervalId = setInterval(() => {
        setTimer((prevTimer) => prevTimer - 1);
      }, 1000);

      return () => clearInterval(intervalId);
    }
  }, [showUndo, timer]);


  return (
    <StyledChatBox
      sx={{
        borderRadius: 2,
        backgroundColor: theme.palette.mode === "light" ? "#fff" : theme.palette.background.paper,
        boxShadow: "0 0 10px rgba(0, 0, 0, 0.1)",
        cursor: 'pointer',
        transition: "0.1s ease-in-out", // Smooth transition effect
        '&:hover': {
          backgroundColor: theme.palette.action.hover, // Change background color on hover
          transform: 'scale(1.05);',
        },
      }}
      p={2}
    >
      <Stack
        direction="row"
        alignItems={"center"}
        justifyContent="space-between"
      >
        <Stack direction="row" alignItems={"center"} spacing={2}>
          {" "}
          {status === "ONLINE" ? (
            <StyledBadge
              overlap="circular"
              anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
              variant="dot"
            >
              <Avatar alt={name} src={avatar} />
            </StyledBadge>
          ) : (
            <Avatar alt={name} src={avatar} />
          )}
          <Stack spacing={0.3}>
            <Typography variant="subtitle2">{name}</Typography>
          </Stack>
        </Stack>
        <Stack direction={"row"} spacing={2} alignItems={"center"}>
          {!showUndo && !removed &&
            (
              <>
                <IconButton
                  onClick={() => {
                    webSocketService.sendMessage("/app/start_conversation", JSON.stringify({ to: id, from: user_id }));
                    handleClose();
                  }}
                >
                  <Chat />
                </IconButton>
                <IconButton
                  onClick={() => { handleRemoveClick() }}
                >
                  <X />
                </IconButton>
              </>
            )
          }
          {showUndo && (
            <Button onClick={handleUndoClick}>
              Undo ({timer}s)
            </Button>
          )}
          {
            removed && <Button disabled variant="text">Removed</Button>
          }
        </Stack>
      </Stack>
    </StyledChatBox>
  );
};

export { UserElement, FriendRequestElement, FriendElement };